import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекст-лаб', quota: 42, status: 'active' },
  { id: 'p2', name: 'Онбординг API', quota: 68, status: 'active' },
  { id: 'p3', name: 'Аналитика событий', quota: 91, status: 'warning' },
  { id: 'p4', name: 'Платёжный шлюз', quota: 100, status: 'over' },
  { id: 'p5', name: 'Мобильный клиент', quota: 15, status: 'active' },
  { id: 'p6', name: 'Внутренний портал', quota: 77, status: 'warning' },
  { id: 'p7', name: 'Экспорт отчётов', quota: 33, status: 'active' },
  { id: 'p8', name: 'Уведомления', quota: 105, status: 'over' },
  { id: 'p9', name: 'Поиск по документам', quota: 54, status: 'active' },
  { id: 'p10', name: 'Интеграция с CRM', quota: 88, status: 'warning' },
  { id: 'p11', name: 'Служба поддержки', quota: 22, status: 'active' },
  { id: 'p12', name: 'Архив логов', quota: 99, status: 'over' },
];

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'В норме',
  warning: 'Близко к лимиту',
  over: 'Превышена',
};

const STATUS_TONE: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  warning: 'warning',
  over: 'danger',
};

const STATUS_FILTERS: ProjectStatus[] = ['active', 'warning', 'over'];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(STATUS_FILTERS);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUS_FILTERS);
    setPage(1);
  };

  const filtered = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const visible = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        padding: '20px',
      }}
    >
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {STATUS_FILTERS.map((status) => (
          <JxChip
            key={status}
            active={activeStatuses.includes(status)}
            removable={activeStatuses.includes(status)}
            onRemove={() => toggleStatus(status)}
            onClick={() => {
              if (!activeStatuses.includes(status)) {
                toggleStatus(status);
              }
            }}
          >
            {STATUS_LABEL[status]}
          </JxChip>
        ))}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          message="Попробуйте выбрать другой статус или сбросить фильтры."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: '16px',
                  padding: '12px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <span style={{ color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}>
                  {project.name}
                </span>
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                  <JxProgressCircle value={Math.min(project.quota, 100)} showValue />
                  <JxBadge tone={STATUS_TONE[project.status]} dot>
                    {STATUS_LABEL[project.status]}
                  </JxBadge>
                </div>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

